alter table public.foncier_land_leads add column if not exists parcel_object_id bigint,add column if not exists parcel_uid text,add column if not exists parcel_geometry jsonb,add column if not exists cadastral_area numeric,add column if not exists geo_sources jsonb not null default '[]'::jsonb,add column if not exists geo_analysis jsonb not null default '{"pga":{"status":"to_verify"},"ppr":{"status":"to_verify"},"road":{"status":"to_verify"},"buildings":{"status":"to_verify"}}'::jsonb;
create table if not exists public.foncier_opportunities(id uuid primary key default gen_random_uuid(),created_at timestamptz not null default now(),created_by uuid references auth.users(id),parcel_object_id bigint not null,parcel_uid text,cadastral_reference text,commune text,island text,cadastral_area numeric,geometry jsonb not null,source jsonb not null,geo_analysis jsonb not null default '{}'::jsonb,potential_projects text[] not null default '{}',status text not null default 'identified',private_notes text,lead_id uuid references public.foncier_land_leads(id),unique(parcel_object_id));
alter table public.foncier_opportunities enable row level security;
create policy "authenticated opportunities" on public.foncier_opportunities for all to authenticated using(true) with check(true);
create index if not exists foncier_opportunity_commune_idx on public.foncier_opportunities(commune,cadastral_area);
comment on column public.foncier_land_leads.cadastral_area is 'Surface m² publiée par la DAF, indicative et distincte de toute contenance officielle vérifiée.';
comment on column public.foncier_land_leads.geo_analysis is 'Observations automatisées uniquement. Ne vaut ni accès juridique, ni constructibilité, ni validation réglementaire.';
